#!/usr/bin/env bash
# Derive the CI Ubuntu sources and their mirror lists from the runner image's
# ubuntu.sources. Hosted runners route Ubuntu through mirror+file:/etc/apt/apt-mirrors.txt,
# whose first entry is the Azure mirror (azure.archive.ubuntu.com). Every stanza that
# uses a mirror list or the Azure mirror reads a SkillPilot mirror list instead: the
# direct Ubuntu endpoint first (security.ubuntu.com for a stanza whose suites are all
# *-security, archive.ubuntu.com otherwise) and the Azure mirror second. APT's mirror
# transport (apt-transport-mirror(1)) moves a file to the next entry when a source fails
# or stalls, and order-ubuntu-mirrors.sh lets a source that answers go first.
# Types, suites, components and Signed-By stay as-is, so whichever mirror serves a file,
# APT verifies it against the same keyring and the signed Release hashes.
set -euo pipefail

if [[ $# -ne 3 ]]; then
  echo "usage: $0 <ubuntu.sources> <output.sources> <mirror-list-directory>" >&2
  exit 2
fi
input=$1
output=$2
mirror_dir=${3%/}
archive_uri=${SKILLPILOT_UBUNTU_ARCHIVE_URI:-https://archive.ubuntu.com/ubuntu/}
security_uri=${SKILLPILOT_UBUNTU_SECURITY_URI:-https://security.ubuntu.com/ubuntu/}
fallback_uri=${SKILLPILOT_UBUNTU_FALLBACK_URI:-http://azure.archive.ubuntu.com/ubuntu/}

if [[ $mirror_dir != /* ]]; then
  echo "The mirror list directory must be an absolute path: $mirror_dir" >&2
  exit 2
fi
test -s "$input"
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT

# Paragraph mode: each deb822 stanza is one record. A rewritten stanza also records
# its list kind and first suite; the list probes that suite's InRelease file.
awk -v mirror_dir="$mirror_dir" -v kinds="$work/kinds" '
  BEGIN { RS = ""; FS = "\n" }
  {
    security = 0
    first_suite = ""
    for (i = 1; i <= NF; i++) {
      if ($i !~ /^Suites:/) continue
      count = split(substr($i, 8), suites, /[ \t]+/)
      security = 1
      seen = 0
      for (j = 1; j <= count; j++) {
        if (suites[j] == "") continue
        seen++
        if (first_suite == "") first_suite = suites[j]
        if (suites[j] !~ /-security$/) security = 0
      }
      if (seen == 0) security = 0
    }
    kind = security ? "security" : "archive"
    if (NR > 1) printf "\n"
    for (i = 1; i <= NF; i++) {
      line = $i
      if (line ~ /^URIs:/ && (line ~ /mirror(\+[a-z]+)*\+file:/ || line ~ /azure\.archive\.ubuntu\.com/)) {
        line = "URIs: mirror+file:" mirror_dir "/" kind ".txt"
        print kind, first_suite > kinds
      }
      print line
    }
  }
' "$input" > "$work/sources"

grep -q '^URIs:' "$work/sources" || { echo "No URIs found in $input" >&2; exit 1; }
if ! awk -v archive="URIs: mirror+file:$mirror_dir/archive.txt" \
         -v security="URIs: mirror+file:$mirror_dir/security.txt" '
  /^URIs:/ && $0 != archive && $0 != security && (/mirror(\+[a-z]+)*\+file:/ || /azure\.archive\.ubuntu\.com/) { bad = 1 }
  END { exit bad }
' "$work/sources"; then
  echo "Image mirror-list or Azure URIs remain in the rendered sources" >&2
  exit 1
fi

# Line order is the preference; order-ubuntu-mirrors.sh only changes the priorities.
write_list() {
  local kind=$1 direct_uri=$2 suite
  [[ -f $work/kinds ]] && grep -q "^$kind " "$work/kinds" || return 0
  suite=$(awk -v kind="$kind" '$1 == kind { print $2; exit }' "$work/kinds")
  {
    printf '# Generated by .github/actions/ubuntu-apt/render-ubuntu-sources.sh (SkillPilot CI).\n'
    printf '# APT mirror list, see apt-transport-mirror(1): APT tries priority 1 first and moves\n'
    printf '# a file that fails or stalls to the next priority. Line order is the preference;\n'
    printf '# before each apt-get update, order-ubuntu-mirrors.sh gives priority 1 to the first\n'
    printf '# entry that serves the probe file.\n'
    if [[ -n $suite ]]; then
      printf '# probe: dists/%s/InRelease\n' "$suite"
    fi
    printf '%s\tpriority:1\n' "$direct_uri"
    printf '%s\tpriority:2\n' "$fallback_uri"
  } > "$work/$kind.txt"
}
write_list archive "$archive_uri"
write_list security "$security_uri"

install -d -m 755 "$mirror_dir"
for kind in archive security; do
  if [[ -f $work/$kind.txt ]]; then
    install -m 644 "$work/$kind.txt" "$mirror_dir/$kind.txt"
  fi
done
install -m 644 "$work/sources" "$output"
